using System;using System.Collections;using System.Collections.Generic;using UnityEngine;
namespace IslandSystem {
// All world actions pass through the same motor as manual play. No inventory/save changes.
public class ActionProgramRunner:MonoBehaviour,IProgramExecutor {
 public bool Running{get;private set;}public int Completed{get;private set;}public string LastError="";
 ActionMotor motor;Coroutine routine;int budget;float deadline;
 void Awake(){motor=GetComponent<ActionMotor>();}
 public static List<ProgramIssue> Check(Draft d){var errors=ProgramValidator.Validate(d);int count=0;float seconds=0;Action<List<Block>,int> visit=null;visit=(list,mult)=>{foreach(var b in list){if(count>400)return;count+=mult;if(b.kind==1||b.kind==7||b.kind==5)errors.Add(new ProgramIssue(b,"此积木仅演示/待接入，不能运行真实动作"));if(b.condition!=null&&b.condition.kind==5)errors.Add(new ProgramIssue(b.condition,"模拟侦测仅供预览，请使用数值比较"));float n;ProgramValidator.Number(b.value,out n);if(b.kind==3)seconds+=n*mult;if(b.kind==8||b.kind==12)seconds+=1.5f*mult;if(b.kind==9)seconds+=1.5f*mult;if(b.kind==10)seconds+=(Mathf.Abs(n)/3.3f+3)*mult;if(b.kind==13)seconds+=3.5f*mult;if(b.kind==11)seconds+=Mathf.Abs(n)/180*mult;visit(b.children,b.kind==2?Mathf.Min(10000,mult*Mathf.Max(1,(int)n)):mult);}};if(errors.Count==0)visit(d.blocks,1);if(count>400)errors.Add(new ProgramIssue(null,"展开后最多400条指令"));if(seconds>180)errors.Add(new ProgramIssue(null,"程序预计超过180秒，请减少循环/等待"));return errors;}
 public void Execute(Draft d){if(Running)throw new InvalidOperationException("程序正在执行，请先停止");var errors=Check(d);if(errors.Count>0)throw new InvalidOperationException(errors[0].message);var guide=FindAnyObjectByType<BeachChapter>();var lesson=guide?guide.LessonIssue(d):null;if(lesson!=null)throw new InvalidOperationException(lesson.message);var snapshot=ProgramCodec.Read(ProgramCodec.Write(d));Running=true;Completed=0;LastError="";budget=400;deadline=Time.time+180;motor.SetProgram(true);routine=StartCoroutine(SafeRun(snapshot));}
 // Manually drive the iterator stack so action failures always release the motor.
 IEnumerator SafeRun(Draft d){var stack=new Stack<IEnumerator>();stack.Push(Sequence(d.blocks));while(stack.Count>0){object next=null;Exception failure=null;bool more=false;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){failure=e;}if(failure!=null){LastError=failure.Message;break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}Running=false;routine=null;motor.SetProgram(false);motor.Status=LastError.Length>0?"程序停止："+LastError:"程序完成 · "+Completed+" 条指令";}
 IEnumerator Sequence(List<Block> blocks){foreach(var b in blocks){if(--budget<0||Time.time>deadline)throw new InvalidOperationException("达到执行安全上限");float n;ProgramValidator.Number(b.value,out n);motor.Status="正在执行："+BlockCatalog.All[b.kind].name;switch(b.kind){case 2:for(int i=0;i<(int)n;i++)yield return Sequence(b.children);break;case 3:yield return new WaitForSeconds(n);break;case 4:float l,r;if(ProgramValidator.Number(b.condition.value,out l)&&ProgramValidator.Number(b.condition.right,out r)&&l>r)yield return Sequence(b.children);break;case 8:case 12:float until=Time.time+4;while(!motor.Grounded){if(Time.time>until)throw new InvalidOperationException("角色尚未落地");yield return null;}if(!motor.Jump(b.kind==12))throw new InvalidOperationException("当前不能跳跃");yield return null;while(!motor.Grounded){if(Time.time>until)throw new InvalidOperationException("跳跃未能正常落地");yield return null;}break;case 9:if(!motor.BeginChop())throw new InvalidOperationException(motor.Status);while(motor.Busy)yield return null;break;case 10:yield return motor.Walk(n);break;case 13:yield return motor.Walk(1.55f);break;case 11:yield return motor.Turn(n);break;}Completed++;}}
 public void Cancel(string reason="程序已取消"){if(routine!=null)StopCoroutine(routine);routine=null;Running=false;if(motor){motor.SetProgram(false);motor.Status=reason;}}
 void OnDisable(){Cancel();}
}
}
